import{_ as l,a0 as o,w as d,s as c,I as i,x as s,a1 as a,A as p,ao as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"cp 命令两个高效的用法 | LCTT x X-CMD","titleTemplate":false,"description":"cp 命令两个高效的用法 | LCTT (201708) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"cp 命令两个高效的用法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"cp 命令两个高效的用法 | LCTT (201708) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201708/20170705 Two great uses for the cp command","title":"cp 命令两个高效的用法","tag":"201708","desc":""},"relativePath":"201708/20170705 Two great uses for the cp command.md","filePath":"[post].md"}'),r={name:"201708/20170705 Two great uses for the cp command.md"};function h(g,e,u,k,b,m){const t=o("Link");return d(),c("div",null,[e[22]||(e[22]=i("h1",{id:"cp-命令两个高效的用法",tabindex:"-1"},[s("cp 命令两个高效的用法 "),i("a",{class:"header-anchor",href:"#cp-命令两个高效的用法","aria-label":"Permalink to “cp 命令两个高效的用法”"},"​")],-1)),e[23]||(e[23]=i("blockquote",null,[i("p",null,"Linux 中高效的备份拷贝命令")],-1)),e[24]||(e[24]=i("p",null,[i("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/car-penguin-drive-linux-yellow.png?itok=ueZE5mph",alt:"Two great uses for the cp command",title:"Two great uses for the cp command"})],-1)),e[25]||(e[25]=i("p",null,[s("在 Linux 上能使用鼠标点来点去的图形化界面是一件很美妙的事……但是如果你喜欢的开发交互环境和编译器是终端窗口、Bash 和 Vim，那你应该像我一样"),i("em",null,"经常"),s("和终端打交道。")],-1)),i("p",null,[e[2]||(e[2]=s("即使是不经常使用终端的人，如果对终端环境深入了解也能获益良多。举个例子—— ",-1)),e[3]||(e[3]=i("code",null,"cp",-1)),e[4]||(e[4]=s(" 命令，据 ",-1)),a(t,{href:"https://en.wikipedia.org/wiki/Cp_(Unix)"},{default:p(()=>[...e[0]||(e[0]=[s("维基百科",-1)])]),_:1}),e[5]||(e[5]=s(" 的解释，",-1)),e[6]||(e[6]=i("code",null,"cp",-1)),e[7]||(e[7]=s(" （意即 copy）命令是第一个版本的 ",-1)),a(t,{href:"https://en.wikipedia.org/wiki/Unix"},{default:p(()=>[...e[1]||(e[1]=[s("Unix",-1)])]),_:1}),e[8]||(e[8]=n(" 系统的一部分。连同一组其它的命令 <code>ls</code>、<code>mv</code>、<code>cd</code>、<code>pwd</code>、<code>mkdir</code>、<code>vi</code>、<code>sh</code>、<code>sed</code> 和 <code>awk</code> ，还有提到的 <code>cp</code> 都是我在 1984 年接触 System V Unix 系统时所学习的命令之一。<code>cp</code> 命令最常见的用法是制作文件副本。像这样：",23))]),e[26]||(e[26]=n(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp sourcefile destfile</span></span></code></pre></div><p>在终端中执行此命令，上述命令将名为 <code>sourcefile</code> 的文件复制到名为 <code>destfile</code> 的文件中。如果在执行命令之前 <code>destfile</code> 文件不存在，那将会创建此文件，如果已经存在，那就会覆盖此文件。</p><p>这个命令我不知道自己用了多少次了（我也不想知道），但是我知道在我编写测试代码的时候，我经常用，为了保留当前正常的版本，而且又能继续修改，我会输入这个命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp test1.py test1.bak</span></span></code></pre></div><p>在过去的30多年里，我使用了无数次这个命令。另外，当我决定编写我的第二个版本的测试程序时，我会输入这个命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp test1.py test2.py</span></span></code></pre></div><p>这样就完成了修改程序的第一步。</p><p>我通常很少查看 <code>cp</code> 命令的参考文档，但是当我在备份我的图片文件夹的时候（在 GUI 环境下使用 “file” 应用），我开始思考“在 <code>cp</code> 命令中是否有个参数支持只复制新文件或者是修改过的文件。”果然，真的有！</p><h3 id="高效用法-1-更新你的文件夹" tabindex="-1">高效用法 1：更新你的文件夹 <a class="header-anchor" href="#高效用法-1-更新你的文件夹" aria-label="Permalink to “高效用法 1：更新你的文件夹”">​</a></h3><p>比如说在我的电脑上有一个存放各种文件的文件夹，另外我要不时的往里面添加一些新文件，而且我会不时地修改一些文件，例如我手机里下载的照片或者是音乐。</p><p>假设我收集的这些文件对我而言都很有价值，我有时候会想做个拷贝，就像是“快照”一样将文件保存在其它媒体。当然目前有很多程序都支持备份，但是我想更为精确的将目录结构复制到可移动设备中，方便于我经常使用这些离线设备或者连接到其它电脑上。</p><p><code>cp</code> 命令提供了一个易如反掌的方法。例子如下：</p><p>在我的 <code>Pictures</code> 文件夹下，我有这样一个文件夹名字为 <code>Misc</code>。为了方便说明，我把文件拷贝到 USB 存储设备上。让我们开始吧！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>me@desktop:~/Pictures$ cp -r Misc /media/clh/4388-D5FE</span></span>
<span class="line"><span>me@desktop:~/Pictures$</span></span></code></pre></div><p>上面的命令是我从按照终端窗口中完整复制下来的。对于有些人来说不是很适应这种环境，在我们输入命令或者执行命令之前，需要注意的是 <code>me@mydesktop:~/Pictures</code> 这个前缀，<code>me</code> 这个是当前用户，<code>mydesktop</code> 这是电脑名称，<code>~/Pictures</code> 这个是当前工作目录，是 <code>/home/me/Pictures</code> 完整路径的缩写。</p><p>我输入这个命令 <code>cp -r Misc /media/clh/4388-D5FE</code> 并执行后 ，拷贝 <code>Misc</code> 目录下所有文件（这个 <code>-r</code> 参数，全称 “recursive”，递归处理，意思为本目录下所有文件及子目录一起处理）到我的 USB 设备的挂载目录 <code>/media/clh/4388-D5FE</code>。</p><p>执行命令后回到之前的提示，大多数命令继承了 Unix 的特性，在命令执行后，如果没有任何异常什么都不显示，在任务结束之前不会显示像 “execution succeeded” 这样的提示消息。如果想获取更多的反馈，就使用 <code>-v</code> 参数让执行结果更详细。</p><p>下图中是我的 USB 设备中刚刚拷贝过来的文件夹 <code>Misc</code> ，里面总共有 9 张图片。</p><p><img src="https://opensource.com/sites/default/files/u128651/cp1_file_structure.png" alt="Image of the new copy of Misc on the USB drive" title="Image of the new copy of Misc on the USB drive"></p><p>假设我要在原始拷贝路径下 <code>~/Pictures/Misc</code> 下添加一些新文件，就像这样：</p><p><img src="https://opensource.com/sites/default/files/u128651/cp2_new_files.png" alt="New files added to the master directory" title="New files added to the master directory"></p><p>现在我想只拷贝新的文件到我的存储设备上，我就使用 <code>cp</code> 的“更新”和“详细”选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>me@desktop:~/Pictures$ cp -r -u -v Misc /media/clh/4388-D5FE</span></span>
<span class="line"><span>&#39;Misc/asunder.png&#39; -&gt; &#39;/media/clh/4388-D5FE/Misc/asunder.png&#39;</span></span>
<span class="line"><span>&#39;Misc/editing tags guayadeque.png&#39; -&gt; &#39;/media/clh/4388-D5FE/Misc/editing tags guayadeque.png&#39;</span></span>
<span class="line"><span>&#39;Misc/misc on usb.png&#39; -&gt; &#39;/media/clh/4388-D5FE/Misc/misc on usb.png&#39;</span></span>
<span class="line"><span>me@desktop:~/Pictures$</span></span></code></pre></div><p>上面的第一行中是 <code>cp</code> 命令和具体的参数（<code>-r</code> 是“递归”， <code>-u</code> 是“更新”，<code>-v</code> 是“详细”）。接下来的三行显示被复制文件的信息，最后一行显示命令行提示符。</p><p>通常来说，参数 <code>-r</code> 也可用更详细的风格 <code>--recursive</code>。但是以简短的方式，也可以这么连用 <code>-ruv</code>。</p><h3 id="高效用法-2-版本备份" tabindex="-1">高效用法 2：版本备份 <a class="header-anchor" href="#高效用法-2-版本备份" aria-label="Permalink to “高效用法 2：版本备份”">​</a></h3><p>回到一开始的例子中，我在开发的时候定期给我的代码版本进行备份。然后我找到了另一种更好用的 <code>cp</code> 参数。</p><p>假设我正在编写一个非常有用的 Python 程序，作为一个喜欢不断修改代码的开发者，我会在一开始编写一个程序简单版本，然后不停的往里面添加各种功能直到它能成功的运行起来。比方说我的第一个版本就是用 Python 程序打印出 “hello world”。这只有一行代码的程序就像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>print &#39;hello world&#39;</span></span></code></pre></div><p>然后我将这个代码保存成文件命名为 <code>test1.py</code>。我可以这么运行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>me@desktop:~/Test$ python test1.py</span></span>
<span class="line"><span>hello world</span></span>
<span class="line"><span>me@desktop:~/Test$</span></span></code></pre></div><p>现在程序可以运行了，我想在添加新的内容之前进行备份。我决定使用带编号的备份选项，如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>clh@vancouver:~/Test$ cp --force --backup=numbered test1.py test1.py</span></span>
<span class="line"><span>clh@vancouver:~/Test$ ls</span></span>
<span class="line"><span>test1.py  test1.py.~1~</span></span>
<span class="line"><span>clh@vancouver:~/Test$</span></span></code></pre></div><p>所以，上面的做法是什么意思呢？</p><p>第一，这个 <code>--backup=numbered</code> 参数意思为“我要做个备份，而且是带编号的连续备份”。所以一个备份就是 1 号，第二个就是 2 号，等等。</p><p>第二，如果源文件和目标文件名字是一样的。通常我们使用 <code>cp</code> 命令去拷贝成自己，会得到这样的报错信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp: &#39;test1.py&#39; and &#39;test1.py&#39; are the same file</span></span></code></pre></div><p>在特殊情况下，如果我们想备份的源文件和目标文件名字相同，我们使用 <code>--force</code> 参数。</p><p>第三，我使用 <code>ls</code> （意即 “list”）命令来显示现在目录下的文件，名字为 <code>test1.py</code> 的是原始文件，名字为 <code>test1.py.~1~</code> 的是备份文件</p><p>假如现在我要加上第二个功能，在程序里加上另一行代码，可以打印 “Kilroy was here.”。现在程序文件 <code>test1.py</code> 的内容如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>print &#39;hello world&#39;</span></span>
<span class="line"><span>print &#39;Kilroy was here&#39;</span></span></code></pre></div><p>看到 Python 编程多么简单了吗？不管怎样，如果我再次执行备份的步骤，结果如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>clh@vancouver:~/Test$ cp --force --backup=numbered test1.py test1.py</span></span>
<span class="line"><span>clh@vancouver:~/Test$ ls</span></span>
<span class="line"><span>test1.py test1.py.~1~ test1.py.~2~</span></span>
<span class="line"><span>clh@vancouver:~/Test$</span></span></code></pre></div><p>现在我有有两个备份文件： <code>test1.py.~1~</code> 包含了一行代码的程序，和 <code>test1.py.~2~</code> 包含两行代码的程序。</p><p>这个很好用的功能，我考虑做个 shell 函数让它变得更简单。</p><h3 id="最后总结" tabindex="-1">最后总结 <a class="header-anchor" href="#最后总结" aria-label="Permalink to “最后总结”">​</a></h3><p>第一，Linux 手册页，它在大多数桌面和服务器发行版都默认安装了，它提供了更为详细的使用方法和例子，对于 <code>cp</code> 命令，在终端中输入如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man cp</span></span></code></pre></div><p>对于那些想学习如何使用这些命令，但不清楚如何使用的用户应该首先看一下这些说明，然后我建议创建一个测试目录和文件来尝试使用命令和选项。</p><p>第二，兴趣是最好的老师。在你最喜欢的搜索引擎中搜索 “linux shell tutorial”，你会获得很多有趣和有用的资源。</p><p>第三，你是不是在想，“为什么我要用这么麻烦的方法，图形化界面中有相同的功能，只用点击几下岂不是更简单？”，关于这个问题我有两个理由。首先，在我们工作中需要中断其他工作流程以及大量使用点击动作时，点击动作可就不简单了。其次，如果我们要完成流水线般的重复性工作，通过使用 shell 脚本和 shell 函数以及 shell 重命名等功能就能很轻松的实现。</p><p>你还知道关于 <code>cp</code> 命令其他更棒的使用方式吗？请在留言中积极回复哦～</p><p>（题图：Opensource.com）</p><hr><p>作者简介：</p><p>Chris Hermansen - 1978 年毕业于英国哥伦比亚大学后一直从事计算机相关职业，我从 2005 年开始一直使用 Linux、Solaris、SunOS，在那之前我就是 Unix 系统管理员了，在技术方面，我的大量的职业生涯都是在做数据分析，尤其是空间数据分析，我有大量的编程经验与数据分析经验，熟练使用 awk、Python、PostgreSQL、PostGIS 和 Groovy。</p><hr>`,57)),i("p",null,[e[10]||(e[10]=s("via: ",-1)),a(t,{href:"https://opensource.com/article/17/7/two-great-uses-cp-command"},{default:p(()=>[...e[9]||(e[9]=[s("https://opensource.com/article/17/7/two-great-uses-cp-command",-1)])]),_:1})]),i("p",null,[e[14]||(e[14]=s("作者：",-1)),a(t,{href:"https://opensource.com/users/clhermansen"},{default:p(()=>[...e[11]||(e[11]=[s("Chris Hermansen",-1)])]),_:1}),e[15]||(e[15]=s(" 译者：",-1)),a(t,{href:"https://github.com/bigdimple"},{default:p(()=>[...e[12]||(e[12]=[s("bigdimple",-1)])]),_:1}),e[16]||(e[16]=s(" 校对：",-1)),a(t,{href:"https://github.com/wxy"},{default:p(()=>[...e[13]||(e[13]=[s("wxy",-1)])]),_:1})]),i("p",null,[e[19]||(e[19]=s("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[17]||(e[17]=[s("LCTT",-1)])]),_:1}),e[20]||(e[20]=s(" 原创编译，",-1)),a(t,{href:"https://linux.cn/"},{default:p(()=>[...e[18]||(e[18]=[s("Linux中国",-1)])]),_:1}),e[21]||(e[21]=s(" 荣誉推出",-1))])])}const C=l(r,[["render",h]]);export{v as __pageData,C as default};
